from flask import Flask, request, jsonify
import json
import os

app = Flask(__name__)

# Internal service registry - populated by service mesh sidecar
_service_registry = {}

class ServiceContext:
    """Holds context for the current service request chain."""
    def __init__(self, caller_identity=None, namespace=None, headers=None):
        self.caller_identity = caller_identity
        self.namespace = namespace
        self.headers = headers
        self._auth_result = None

    def get_auth_result(self):
        return self._auth_result

    def set_auth_result(self, result):
        self._auth_result = result


def parse_upstream_context(headers):
    """Parse the x-upstream-context header injected by the sidecar proxy.
    Returns ServiceContext or None if header is missing/malformed."""
    raw = headers.get('X-Upstream-Context')
    if not raw:
        return None
    try:
        data = json.loads(raw)
        return ServiceContext(
            caller_identity=data.get('identity'),
            namespace=data.get('namespace'),
            headers=headers
        )
    except (json.JSONDecodeError, TypeError):
        return None


def get_user_profile(user_id, ctx):
    """Fetch user profile. ctx may be None for direct calls."""
    # Simulated DB lookup
    profiles = {
        "1": {"name": "Alice", "email": "alice@corp.internal", "role": "admin", "ssn": "123-45-6789"},
        "2": {"name": "Bob", "email": "bob@corp.internal", "role": "user", "ssn": "987-65-4321"},
        "3": {"name": "Charlie", "email": "charlie@corp.internal", "role": "user", "ssn": "555-12-3456"},
    }
    profile = profiles.get(user_id)
    if profile is None:
        return None

    # VULNERABILITY: If ctx is None (no upstream context), we dereference it
    # attempting to check authorization. This crashes the app but also
    # the exception handler below leaks sensitive data in debug mode.
    caller_ns = ctx.namespace  # NullPointerDereference if ctx is None

    if caller_ns == "trusted-frontend":
        return profile
    else:
        # Strip sensitive fields for non-trusted callers
        return {"name": profile["name"], "email": profile["email"], "role": profile["role"]}


@app.route('/api/v1/users/<user_id>/profile', methods=['GET'])
def user_profile_endpoint(user_id):
    ctx = parse_upstream_context(request.headers)
    try:
        profile = get_user_profile(user_id, ctx)
        if profile is None:
            return jsonify({"error": "User not found"}), 404
        return jsonify(profile), 200
    except AttributeError as e:
        # In production this should return 500, but the error message
        # includes the locals() dump when FLASK_DEBUG is set
        if os.environ.get('FLASK_DEBUG', '0') == '1':
            import traceback
            # Leak: includes the profile variable which was already fetched
            frame_locals = {}
            tb = e.__traceback__
            while tb.tb_next:
                tb = tb.tb_next
            frame_locals = tb.tb_frame.f_locals
            return jsonify({
                "error": str(e),
                "debug_context": {k: str(v) for k, v in frame_locals.items()}
            }), 500
        return jsonify({"error": "Internal server error"}), 500


@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "healthy"}), 200


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
